/* Harbour Mutual Bank (Financial services) - source database seed for the pipeline Copy demo
   Plays the role of: Core banking platform (on-prem SQL Server)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.accounts; DROP TABLE IF EXISTS src.risk_cases; DROP TABLE IF EXISTS src.stage_accounts; DROP TABLE IF EXISTS src.stage_risk_cases;
CREATE TABLE src.accounts (account_id INT NOT NULL, account_number NVARCHAR(30), account_name NVARCHAR(100), product_type NVARCHAR(30), state NVARCHAR(40), status NVARCHAR(30), risk_grade INT, balance_aud DECIMAL(12,1), open_date DATE, last_modified DATETIME2(0), CONSTRAINT pk_accounts PRIMARY KEY (account_id));
CREATE TABLE src.risk_cases (case_id INT NOT NULL, account_id INT, case_type NVARCHAR(30), priority INT, status NVARCHAR(30), raised_ts DATETIME2(0), closed_ts DATETIME2(0), case_amount_aud DECIMAL(12,2), analyst_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_risk_cases PRIMARY KEY (case_id));
CREATE TABLE src.stage_accounts (release_day INT NOT NULL, account_id INT, account_number NVARCHAR(30), account_name NVARCHAR(100), product_type NVARCHAR(30), state NVARCHAR(40), status NVARCHAR(30), risk_grade INT, balance_aud DECIMAL(12,1), open_date DATE, last_modified DATETIME2(0), hardship_flag NVARCHAR(50));
CREATE TABLE src.stage_risk_cases (release_day INT NOT NULL, case_id INT, account_id INT, case_type NVARCHAR(30), priority INT, status NVARCHAR(30), raised_ts DATETIME2(0), closed_ts DATETIME2(0), case_amount_aud DECIMAL(12,2), analyst_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.accounts', 'hardship_flag') IS NULL
        EXEC('ALTER TABLE src.accounts ADD hardship_flag NVARCHAR(50) NULL');
    DELETE t FROM src.accounts t WHERE EXISTS (SELECT 1 FROM src.stage_accounts s WHERE s.release_day = @day AND s.account_id = t.account_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.hardship_flag = s.hardship_flag FROM src.accounts t JOIN src.stage_accounts s ON s.account_id = t.account_id AND s.release_day = 3');
    DELETE t FROM src.risk_cases t WHERE EXISTS (SELECT 1 FROM src.stage_risk_cases s WHERE s.release_day = @day AND s.case_id = t.case_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.accounts) AS accounts, (SELECT COUNT(*) FROM src.risk_cases) AS risk_cases;
END;
GO
